const $=s=>document.querySelector(s);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Math.floor(n).toLocaleString('it-IT');
const time=n=>{const s=Math.max(0,Math.ceil(n/1000));if(s>=86400)return `${Math.floor(s/86400)}g ${Math.floor(s%86400/3600)}h`;if(s>=3600)return `${Math.floor(s/3600)}h ${Math.floor(s%3600/60)}m`;return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`};
const labels={materials:'Materiali',food:'Cibo',reagents:'Reagenti',energy:'Reagenti',credits:'Crediti'};
let state=null,catalog=null,source=null,page='overview',selected=null,starter='bulbasaur',dexMode='owned',dexSearch='',connected=false,loginMode=false,config={authRequired:false},lastUI=0,lastPane=0,lastChat='',lastJournal='',toastTimer,missionKind='survey',missionSpecies='',missionBall='ball',missionTool='',missionTalentType='',dexType='',dexRarity='',dexDuty='',workPreview=null,assignmentDrafts={},initialTalentDrafts={};
let selectedSquad = 'alpha';
