const sprite=(s,cls='')=>`<img class="${cls}" src="${escape(s.sprite)}" alt="${escape(s.name)}" width="96" height="96" loading="lazy">`;
const facilityArt=(id)=>`<div class="facility-art"><img src="/assets/${id}.jpg" alt="" loading="lazy" width="768" height="512"></div>`;
