function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500)}
async function api(url,data){const res=await fetch(url,data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{});const body=await res.json();if(!res.ok)throw Error(body.error||'Richiesta fallita.');return body}
async function command(data){if(!connected){toast('Connessione assente: attendi la riconnessione.');return false}try{await api('/api/command',data);state=await api('/api/me');render(true);return true}catch(err){toast(err.message);return false}}
function sData(id){return catalog.species.find(s=>s.id===id)}
function registered(p){return new Set([...p.creatures.map(c=>c.species),...(p.observed||[])])}
function selectedObject(){return state?.world.tiles.find(t=>t.x+':'+t.y===selected)}
function openGame(snapshot){state=snapshot;$('#welcome').hidden=true;$('#app').hidden=false;$('#trainer-name').textContent='Ric. '+state.me.name;navigate('overview');connect();camera.x=state.me.baseTile.x;camera.y=state.me.baseTile.y;render(true)}
function connect(){source?.close();source=new EventSource('/api/events');source.onopen=()=>{connected=true;$('#connection').textContent='● In diretta';$('#connection').classList.remove('offline')};source.onmessage=e=>{state=JSON.parse(e.data);render()};source.onerror=()=>{connected=false;$('#connection').textContent='● Riconnessione…';$('#connection').classList.add('offline')};}
function costText(cost){return Object.entries(cost).map(([k,v])=>`${num(v)} ${(labels[k]||k).toLowerCase()}`).join(' · ')}
function afford(cost){return Object.entries(cost).every(([k,v])=>state.me.resources[k]>=v)}
function itemCount(p,id){return id==='ball'?p.balls:id==='potion'?p.potions:(p.equipment?.[id]||0)}
function fieldInventory(p) {
 return Object.entries(catalog.fieldMaterials??{}).map(([id,material])=>`<div class="inventory-row"><span>${escape(material.name)}</span><strong>${num(p.resources[id]??0)}</strong></div>`).join('');
}
function inventoryMarkup(p){return `<div class="inventory-row"><span>◒ Poké Ball</span><strong>${p.balls}</strong></div><div class="inventory-row"><span>✚ Pozioni <strong>${p.potions}</strong></span><button class="quiet" data-command="potion" ${p.mission||!p.potions||p.potionUntil>state.time||p.team.every(id=>p.creatures.find(c=>c.id===id).hp>=p.creatures.find(c=>c.id===id).maxHp)?"disabled":""}>Usa</button></div>${Object.entries(p.equipment).filter(([,n])=>n>0).map(([id,n])=>`<div class="inventory-row"><span>${catalog.recipes.find(r=>r.id===id)?.name||escape(id)}</span><strong>${n}</strong></div>`).join('')}${fieldInventory(p)}<div class="inventory-row muted small"><span>Habitat</span><span>${p.creatures.length}/${p.capacity}</span></div><button class="quiet" data-page="craft">Fabbrica strumenti →</button>${p.craftJob?`<p class="small muted">${p.craftJob.quantity} × ${catalog.recipes.find(r=>r.id===p.craftJob.id).name} · ${time(p.craftJob.end-state.time)}</p>`:''}`}
function craftQueue(p){return `<div class="operation-row"><span class="op-icon">⚒</span><div><strong>Fabbricazione</strong><p>${p.craftJob?p.craftJob.quantity+' × '+catalog.recipes.find(r=>r.id===p.craftJob.id).name:'Nessun lotto in produzione'}</p></div><span class="op-time">${p.craftJob?time(p.craftJob.end-state.time):'Libera'}</span><button class="quiet" data-page="craft">Strumenti</button></div>`}
document.addEventListener('change',e=>{if(e.target.dataset.production)command({type:'production',id:e.target.dataset.production,percent:Number(e.target.value)})});
document.addEventListener('click',e=>{const b=e.target.closest('[data-craft]');if(b){b.disabled=true;command({type:'craft',id:b.dataset.craft,quantity:Number($('#qty-'+b.dataset.craft).value)})}});

function refreshEnergyCounters(p){const e=p.power,values=[num(e.produced),num(e.consumed),(e.balance>0?'+':'')+num(e.balance),Math.round(e.factor*100)+'%'];document.querySelectorAll('.energy-summary>div>strong').forEach((el,i)=>{el.textContent=values[i];if(i===2)el.parentElement.classList.toggle('power-deficit',e.balance<0)});document.querySelectorAll('.energy-row:not(.energy-head)').forEach((row,i)=>{const id=['generator','quarry','farm','refinery'][i],resource={quarry:'materials',farm:'food',refinery:'reagents'}[id];row.children[2].textContent=id==='generator'?'+ '+num(e.produced):'− '+(e.byPlant[id]||0).toLocaleString('it-IT',{maximumFractionDigits:1});row.children[3].textContent=resource?num(p.rates[resource]*3600)+' '+labels[resource].toLowerCase()+'/h':'Potenza continua'})}
function memberMarkup(c){const s=c.speciesData;return `<div class="member"><div class="portrait">${sprite(s)}</div><div class="member-info"><strong>${escape(s.name)}</strong><span class="level">Liv. ${c.level}</span><div class="type">${s.types.join(" / ")} · ${s.role}</div><div class="hp ${c.hp/c.maxHp<.3?'low':''}"><span style="width:${Math.max(0,c.hp/c.maxHp*100)}%"></span></div><div class="hp-text"><span>${num(c.hp)} / ${c.maxHp} PS</span><span>XP ${c.xp}/${c.level*35}</span></div></div></div>`}
function render(force=false){if(!state)return;const now=Date.now(),p=state.me;if(!force&&now-lastUI<350)return;lastUI=now;
 $('#resources').innerHTML=['materials','food','reagents','credits'].map(k=>[k,p.resources[k]]).map(([k,v])=>`<div class="resource"><label>${labels[k].toUpperCase()}</label><strong>${num(v)}</strong>${p.rates[k]?`<small>+${num(p.rates[k]*3600)}/h</small>`:k!=="credits"&&p.resources[k]>=p.cap?'<small>Magazzino pieno</small>':''}</div>`).join('')+`<button class="resource resource-power ${p.power.balance<0?'power-deficit':''}" data-page="energy"><label>ENERGIA</label><strong>${num(p.power.balance)} / ${num(p.power.produced)}</strong><small>Bilancio / prodotta · ${Math.round(p.power.factor*100)}%</small></button>`;
 $('#world-clock').textContent=new Date(state.time).toLocaleTimeString('it-IT');$('.alpha-note').innerHTML=(config.online?'ALPHA ONLINE':'ALPHA LOCALE')+' · 0.3<br>Salvataggio automatico';const online=state.world.players.filter(o=>o.online).length;$('#online-count').textContent=online+(online===1?' ricercatore online':' ricercatori online');
 $('#team-list').innerHTML=p.team.map(id=>memberMarkup(p.creatures.find(c=>c.id===id))).join('')+(p.team.length<p.teamLimit?`<div class="empty-slot">${p.teamLimit-p.team.length} posti liberi · Cattura nuovi Pokémon</div>`:'');
 $('#team-status').textContent=p.mission?({outbound:'IN VIAGGIO',onsite:'SUL CAMPO',returning:'IN RIENTRO'}[p.mission.phase]):'ALL’AVAMPOSTO';
 $('#team-actions').innerHTML=missionPanel(p);
 $('#hq-level').textContent='LIVELLO '+p.buildings.hq;$('#build-progress').innerHTML=p.buildJob?`<div class="progress-meta"><span>${escape(catalog.buildings.find(b=>b.id===p.buildJob.id).name)}</span><span>${time(p.buildJob.end-state.time)}</span></div><div class="progress"><span style="width:${Math.min(100,(state.time-p.buildJob.start)/(p.buildJob.end-p.buildJob.start)*100)}%"></span></div>`:'<p class="small muted">Nessuna costruzione in corso.</p><button class="quiet" data-page="base">Sviluppa la base →</button>';
 $('#inventory').innerHTML=inventoryMarkup(p);
 $('#pvp-toggle').closest('label').hidden=true;
 if(force||!$('#target-panel').contains(document.activeElement))renderTarget();
 const journalKey=p.messages.map(m=>m.id).join();if(journalKey!==lastJournal){lastJournal=journalKey;$('#journal-list').innerHTML=p.messages.slice(-4).reverse().map(m=>`<div class="journal-entry">${escape(m.text)}<time>${new Date(m.time).toLocaleTimeString('it-IT')}</time></div>`).join('')}
 renderChat();if(page==='energy')refreshEnergyCounters(p);
 const ready=catalog.quests.filter(q=>p.progress[q.id]>=q.goal&&!p.claimed.includes(q.id));$('#quest-count').textContent=ready.length;
 const next=catalog.quests.find(q=>!p.claimed.includes(q.id));$('#tutorial').innerHTML=next?`<span>☷</span><div><strong>${escape(next.name)}</strong><p>${escape(next.desc)}</p></div><button class="${p.progress[next.id]>=next.goal?'primary':'quiet'}" ${p.progress[next.id]>=next.goal?`data-command="claim" data-id="${next.id}"`:'data-page="quests"'}>${p.progress[next.id]>=next.goal?'Riscatta premio':'Vedi incarichi →'}</button>`:'<span>✓</span><div><strong>Ricercatore della Frontiera</strong><p>Incarichi iniziali completati. Nuovi dati per la spedizione Aurora.</p></div>';
 if(force||now-lastPane>1000){lastPane=now;if(page!=='map'&&(force||!$('#page-content').contains(document.activeElement)))renderPage();renderMap();renderGatherSites()}

}
function renderChat(){const channel=$('#chat-channel').value;const messages=state.chat.filter(c=>channel==='alliance'?c.alliance===state.me.alliance&&c.alliance:!c.alliance);const key=channel+messages.map(c=>c.id).join();if(key===lastChat)return;lastChat=key;const list=$('#chat-list');list.innerHTML=messages.length?messages.map(c=>`<div class="chat-message"><strong>${escape(c.name)}</strong> ${escape(c.text)}</div>`).join(''):'<p class="muted">La radio è silenziosa. Saluta gli altri ricercatori.</p>';list.scrollTop=list.scrollHeight}
function habitatStatus(tile) {
 const availability = tile.availability;
 if (!availability) return '';
 const recovery = availability.stockNextAt
  ? ` · +${availability.stockRecovery} fra ${time(availability.stockNextAt-state.time)}`
  : ' · riserva piena';
 return `<p class="small habitat-stock"><strong>Riserva condivisa</strong> · ${num(tile.stock)}/${availability.stockCapacity} ${labels[tile.resource].toLowerCase()}${recovery}</p>`;
}
function habitatPopulation(tile,id) {
 const population = tile.availability?.populations[id];
 if (!population) return '';
 const recovery = population.nextAt ? ` · +1 fra ${time(population.nextAt-state.time)}` : '';
 return `<small class="${population.count?'':'gold'}">${population.count}/${population.capacity} presenti${recovery}</small>`;
}
function squadPicker(p) {
 const lock = p.betaLock;
 if (!lock) return '';
 const picker = `<label>Squadra<select id="mission-squad"><option value="alpha" ${selectedSquad==='alpha'?'selected':''}>Alfa${p.mission?' · impegnata':''}</option><option value="beta" ${selectedSquad==='beta'?'selected':''} ${lock.ok?'':'disabled'}>Beta${lock.ok?(p.betaMission?' · impegnata':''):' · da sbloccare'}</option></select></label>`;
 if (!lock.ok) return picker + `<p class="small muted">Beta richiede ${lock.missing.map(escape).join(' · ')}.</p>`;
 if (selectedSquad==='alpha') return picker;
 if (p.betaMission) return picker + '<p class="small muted">La Beta è in spedizione.</p>';
 const options = p.creatures.filter(c=>p.betaCandidates.includes(c.id));
 if (!options.length) return picker + '<p class="small muted">Nessun Pokémon in riserva disponibile per la Beta.</p>';
 return picker + `<fieldset class="beta-roster"><legend>Formazione Beta · scegli 1–2 Pokémon in riserva</legend>${options.map(c=>`<label><input type="checkbox" data-beta-member="${escape(c.id)}" ${betaRosterDraft.has(c.id)?'checked':''}>${escape(c.speciesData.name)} · liv. ${c.level} · ${num(c.hp)} PS</label>`).join('')}</fieldset>`;
}
function missionTalentBonus(roster, kind, effect) {
 const values = roster.map(c=>c.talent).filter(t=>t?.effect===effect&&t.missions.includes(kind))
  .map(t=>t.value).sort((a,b)=>b-a).slice(0,3);
 return Math.min(effect==='foodCost'?.2:.25,values.reduce((sum,n,i)=>sum+n*[1,.5,.25][i],0));
}
function plannedRoster(p) {
 return selectedSquad==='beta' ? betaRoster(p) : p.creatures.filter(c=>p.team.includes(c.id));
}
function expeditionEstimate(p,tile,roster,mission) {
 const kind = catalog.missions[mission];
 const slowest = members=>Math.min(100,...members.map(c=>c.speciesData.baseStats.speed));
 const alpha = p.creatures.filter(c=>p.team.includes(c.id));
 const speed = p.travelSpeed*(100+slowest(roster))/(100+slowest(alpha));
 const distance = Math.hypot(tile.x-p.baseTile.x,tile.y-p.baseTile.y);
 const bonus = effect=>missionTalentBonus(roster,mission,effect);
 const travel = Math.ceil(Math.max(45000/state.profile.speed,Math.ceil(distance/speed*1000))/(1+bonus('travel')));
 const siteWork = mission==='gather' ? tile.site?.work ?? 1 : 1;
 const work = Math.ceil(kind.work*siteWork/(1+bonus('work')));
 const food = Math.ceil((kind.food+Math.ceil(distance*2)+roster.length*3)*(1-bonus('foodCost')));
 return {distance,travel,work,food};
}
function gatheringEstimate(p,tile,roster,tool) {
 const living = roster.filter(c=>c.hp>0).length;
 const capacity = Math.round((p.gatherUnitLoad??15)*living*(catalog.recipes.find(r=>r.id===tool)?.loadFactor??1)*
  (1+missionTalentBonus(roster,'gather','gather'))*(tile.site?.load??1));
 return {capacity,load:Math.min(tile.stock,capacity)};
}
function fieldSampleMarkup(tile) {
 const sample=tile.sample;
 if (!sample) return '';
 const recovery=sample.nextAt ? ` · +1 fra ${time(sample.nextAt-state.time)}` : '';
 return `<p class="small habitat-stock"><strong>${escape(labels[sample.id])}</strong> · ${sample.count}/${sample.capacity} in comune${recovery} · 1 per raccolta se disponibile</p>`;
}
function gatheringSiteMarkup(tile) {
 if (!tile.site) return '';
 const site = tile.site;
 const bonus = Math.round((site.load-1)*100);
 const work = Math.round((site.work-1)*100);
 return `<p class="small site-description"><strong>${escape(site.name)}</strong>${site.type==='deep'?` · +${bonus}% carico · +${work}% tempo sul campo · recupero riserva più lento`:' · tempi e carico standard'}</p>`;
}
let lastSiteComparison = '';
function renderGatherSites() {
 if (page!=='map'||!state||!$('#site-comparison').open) return;
 const p = state.me;
 const resource = $('#site-resource').value;
 const roster = plannedRoster(p);
 const sites = state.world.tiles.filter(t=>t.site && !t.owner && (!resource||t.resource===resource||t.sample?.id===resource) &&
  t.difficulty<=p.missionDifficulty && Math.hypot(t.x-p.baseTile.x,t.y-p.baseTile.y)<=p.missionRange);
 const tool = missionKind==='gather' ? missionTool : '';
 const rows = sites.map(tile=>{
  const {load}=gatheringEstimate(p,tile,roster,tool);
  const estimate=expeditionEstimate(p,tile,roster,'gather');
  return {tile,load,eta:estimate.travel*2+estimate.work,food:estimate.food};
 }).sort((a,b)=>catalog.fieldMaterials?.[resource] ? Number(b.tile.sample.count>0&&b.load>0)-Number(a.tile.sample.count>0&&a.load>0)||a.eta-b.eta : b.load-a.load||a.eta-b.eta);
 const lock=p.locks.missions.gather;
 const markup = `<p class="small muted">Squadra ${squadName(selectedSquad)}${tool?' · '+escape(catalog.recipes.find(r=>r.id===tool)?.name||tool):''}. Carico stimato con le scorte attuali.${lock.ok?'':` Raccolta da sbloccare · ${lock.missing.map(escape).join(', ')}.`}</p>` + (rows.length ? `<div class="site-table-scroll"><table class="site-table"><thead><tr><th scope="col">Sito</th><th scope="col">Riserva</th><th scope="col">Carico</th><th scope="col">Campioni</th><th scope="col">Totale</th><th scope="col">Cibo</th></tr></thead><tbody>${rows.map(({tile,load,eta,food})=>`<tr><th scope="row"><button data-select="${tile.x}:${tile.y}" data-gather-site>${escape(tile.site.name)} (${tile.x}|${tile.y})</button><small>${labels[tile.resource]}</small></th><td>${num(tile.stock)}</td><td>${num(load)}</td><td>${tile.sample?`${tile.sample.count}/${tile.sample.capacity} ${escape(labels[tile.sample.id].toLowerCase())}`:'—'}</td><td>${time(eta)}</td><td>${food}</td></tr>`).join('')}</tbody></table></div>` : '<p class="small muted">Nessun sito esplorato e raggiungibile per questa risorsa.</p>');
 if (markup===lastSiteComparison) return;
 lastSiteComparison=markup;
 $('#nearby-list').innerHTML=markup;
}
function renderTarget(){
 const p=state.me,t=selectedObject();if(!t){$('#target-panel').innerHTML='<div><h2>Seleziona una casella</h2><p class="muted small">Sblocca tecnologie, prepara gli strumenti e invia una spedizione.</p></div>';return}
 const biome=catalog.biomes[t.biome];if(t.owner){$('#target-panel').innerHTML=`<div><h2>⌂ Avamposto ${escape(t.owner.name)}</h2><p class="muted small">(${t.x}|${t.y}) · Insediamento protetto</p></div>`;return}
 if(!t.known)missionKind='survey';const id=t.encounters.includes(missionSpecies)?missionSpecies:t.encounters.find(sid=>t.availability?.populations[sid]?.count>0)||t.encounters[0],kind=catalog.missions[missionKind];
 const roster = plannedRoster(p);
 const {distance,travel,work,food}=expeditionEstimate(p,t,roster,missionKind);
 const gather = gatheringEstimate(p,t,roster,missionTool);
 const activeMission = selectedSquad==='beta' ? p.betaMission : p.mission;
 const issues=[...p.locks.missions[missionKind].missing];if(distance>p.missionRange)issues.push('Fuori raggio: Osservatorio e Logistica richiesti.');if(t.difficulty>p.missionDifficulty)issues.push('Difficoltà superiore al limite: sviluppa Cartografia.');if(missionKind==='capture'&&id)issues.push(...p.speciesLocks[id].missing);if(p.resources.food<food)issues.push('Cibo insufficiente.');if(activeMission)issues.push('Squadra già impegnata.');if(!roster.some(c=>c.hp>0))issues.push(selectedSquad==='beta'?'Scegli almeno un Pokémon in riserva.':'Prepara una squadra in salute dal Pokédex.');if(missionKind==='capture'&&p.capturePlaces===0)issues.push('Nessun posto libero nell’Habitat per la cattura.');if(missionKind==='capture'&&id&&sData(id).types.length===2&&!sData(id).types.includes(missionTalentType))issues.push('Scegli il tipo dell’abilità per questa cattura.');
 if (missionKind==='gather' && t.stock===0) issues.push('Riserva esaurita. Attendi il recupero o scegli un’altra casella.');
 if (['capture','study'].includes(missionKind) && t.availability?.populations[id]?.count===0) issues.push('Popolazione esaurita. Attendi il ripopolamento o scegli un altro habitat.');
 if (missionKind==='battle' && t.availability && !Object.values(t.availability.populations).some(p=>p.count>0)) issues.push('Nessun Pokémon disponibile per il contenimento.');
 const tools=catalog.recipes.filter(r=>r.mission===missionKind).map(r=>r.id);if(!tools.includes(missionTool))missionTool='';
 $('#target-panel').innerHTML=`<div class="tile-detail"><div class="panel-heading"><h2>${biome.icon} ${biome.name} (${t.x}|${t.y})</h2><span class="tag">${t.known?'NOTA':'DA ESPLORARE'}</span></div><p class="small muted">Difficoltà ${t.difficulty}/${p.missionDifficulty} · Dal tuo avamposto ${distance.toFixed(1)}/${p.missionRange} caselle</p>${habitatStatus(t)}${gatheringSiteMarkup(t)}${fieldSampleMarkup(t)}${t.known?`<div class="habitat-species">${t.encounters.map(sid=>{const s=sData(sid);return `<span>${sprite(s)}<b>${s.name}</b><small>${s.types.join(' / ')}</small>${habitatPopulation(t,sid)}</span>`}).join('')}</div>`:'<p class="unexplored-note">La ricognizione rivela presenze e riserve della casella.</p>'}<div class="dispatch-form">${squadPicker(p)}<label>Missione<select id="mission-kind">${Object.entries(catalog.missions).map(([mid,m])=>`<option value="${mid}" ${mid===missionKind?'selected':''} ${(!t.known&&mid!=='survey')||!p.locks.missions[mid].ok?'disabled':''}>${m.name}${!p.locks.missions[mid].ok?' · bloccata':''}</option>`).join('')}</select></label>${['study','capture'].includes(missionKind)?`<label>Specie<select id="mission-species">${t.encounters.map(sid=>`<option value="${sid}" ${sid===id?'selected':''}>${sData(sid).name}${missionKind==='capture'&&!p.speciesLocks[sid].ok?' · requisiti mancanti':''}</option>`).join('')}</select></label>`:''}${missionKind==='capture'?talentCaptureMarkup(id):''}${missionKind==='capture'?`<label>Ball<select id="mission-ball">${['ball','greatBall','ultraBall'].map(b=>`<option value="${b}" ${missionBall===b?'selected':''} ${!itemCount(p,b)?'disabled':''}>${catalog.recipes.find(r=>r.id===b).name} (${itemCount(p,b)})</option>`).join('')}</select></label>`:''}${tools.length?`<label>Strumento consumabile<select id="mission-tool"><option value="">Nessuno</option>${tools.map(tool=>`<option value="${tool}" ${missionTool===tool?'selected':''} ${!itemCount(p,tool)?'disabled':''}>${catalog.recipes.find(r=>r.id===tool).name} (${itemCount(p,tool)})</option>`).join('')}</select></label>`:''}<div class="dispatch-estimate"><span>Andata<b>${time(travel)}</b></span><span>Operazione<b>${time(work)}</b></span><span>Totale<b>${time(travel*2+work)}</b></span></div>${missionKind==='gather'?`<p class="small"><strong>Carico stimato ${gather.load}/${gather.capacity}</strong> ${labels[t.resource].toLowerCase()}</p>`:''}<p class="small muted">${food} cibo${missionKind==='capture'?' + 1 Ball':''}${missionTool?' + 1 strumento':''} · Continuazione offline</p>${t.known&&missionKind!=='survey'?'<p class="small muted">Disponibilità condivisa, verificata al termine dell’operazione.</p>':''}${issues.length?`<div class="requirement">${issues.map(escape).join('<br>')}</div>`:''}<button class="primary" data-dispatch ${issues.length?'disabled':''}>Invia spedizione →</button><details class="unlock-details"><summary>Missioni da sbloccare</summary>${Object.entries(p.locks.missions).filter(([,l])=>!l.ok).map(([mid,l])=>`<p><strong>${catalog.missions[mid].name}</strong>: ${l.missing.map(escape).join(', ')}</p>`).join('')||'<p>Tutti i tipi di missione disponibili.</p>'}</details></div></div>`;
}

const pageInfo={technology:['RICERCA / ALBERO TECNOLOGICO','Tecnologie e prerequisiti','Pianifica gli sblocchi e confronta gli effetti di ogni livello.'],staff:['AVAMPOSTO / PERSONALE','Pokémon al lavoro','Organizza mansioni, abilità e automazione.'],account:['IDENTITÀ / RICERCATORE','Il tuo account','Accesso da altri browser e preparazione alla versione online.'],energy:['RETE ENERGETICA / PRODUZIONE','Bilancio energetico','Capacità prodotta, consumo degli impianti ed efficienza reale.'],craft:['STRUTTURE / FABBRICAZIONE','Strumenti della spedizione','Ricette, prerequisiti e lotti di produzione.'],missions:['COORDINAMENTO / DALL’AVAMPOSTO AL TERRITORIO','Spedizioni','Partenza, arrivo, operazione e rientro: ogni evento è gestito dal server.'],reports:['ARCHIVIO / RICERCA SUL CAMPO','Rapporti di missione','Esiti, specie osservate e carichi delle tue spedizioni.'],overview:['SPEDIZIONE AURORA / STAZIONE DI RICERCA','Panoramica dell’avamposto','Ricerca, sviluppo e coordinamento nelle terre selvagge.'],map:['VALLE DI ASTER / TERRE SELVAGGE','Territorio di ricerca','Seleziona una casella, consulta il rapporto e invia una squadra dal tuo avamposto.'],base:['AVAMPOSTO / SVILUPPO','Il tuo avamposto di ricerca.','Produci, costruisci e prepara la tua prossima esplorazione.'],collection:['COLLEZIONE / PRIMA GENERAZIONE','Il tuo Pokédex di Kanto.','151 specie da scoprire. Cambia formazione quando sei alla base.'],research:['LABORATORIO / TECNOLOGIE','La conoscenza fa la differenza.','Specializza la tua squadra e migliora le tue attrezzature.'],market:['LOGISTICA / MERCATO','Mercato e convogli','Compra strumenti da altri ricercatori e segui le consegne dei rover.'],alliance:['COMUNITÀ / ALLEANZE','Insieme, più lontano.','Coordina la ricerca con gli altri avamposti della spedizione.'],ranking:['SPEDIZIONE AURORA / PRESTIGIO','I protagonisti della frontiera.','Vittorie, catture e boss costruiscono la tua reputazione.'],quests:['RICERCA SUL CAMPO / INCARICHI','Una direzione per ogni viaggio.','Completa gli obiettivi e riscatta le ricompense.']};
function navigate(next){if(!pageInfo[next])return;page=next;document.querySelectorAll('.sidebar [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#page-map').hidden=page!=='map';$('#page-content').hidden=page==='map';const info=pageInfo[page];$('#page-kicker').textContent=info[0];$('#page-title').textContent=info[1];$('#page-desc').textContent=info[2];if(page!=='map')renderPage();else renderMap(true)}
function renderPage(){const p=state.me,pane=$('#page-content');
 if(page==='account'){pane.innerHTML=`<div class="help-card"><strong>Ricercatore ${escape(p.name)}</strong><p>${state.account.hasPassword?'Account protetto: puoi accedere con nome e password da un altro browser.':'Questa sessione locale non ha ancora una password. Impostala per poter ritrovare i progressi da altri dispositivi.'}</p></div>${!state.account.hasPassword?'<form id="claim-account" class="card account-form"><label for="claim-password">Nuova password</label><input id="claim-password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required placeholder="Almeno 12 caratteri"><button class="primary" type="submit">Proteggi account</button></form>':''}<div class="help-card">Profilo ${state.profile.name} ×${state.profile.speed}. Non è ancora previsto il recupero tramite email: conserva la password in modo sicuro.</div><button class="quiet" data-logout>Esci dall’account</button>`;}
 if(page==='overview'){
  const job=p.buildJob,tech=p.researchJob,m=p.mission;
  const activity=m?catalog.missions[m.type].name+' · ('+m.destination.x+'|'+m.destination.y+') · '+({outbound:'Andata',onsite:'Sul campo',returning:'Rientro'}[m.phase]):'Alfa disponibile';
  const eta=m?time((m.phase==='outbound'?m.arriveAt:m.phase==='onsite'?m.completeAt:m.returnAt)-state.time):'—';
  pane.innerHTML=`<div class="operation-bar"><span>AVAMPOSTO 01 <b>(${p.baseTile.x}|${p.baseTile.y})</b></span><span>Valle di Aster · Zona protetta</span><span class="gold">CENTRO OPERATIVO ${p.buildings.hq}</span></div><div class="outpost-hero"><img class="outpost-art" src="/assets/outpost.jpg" alt="Avamposto scientifico nella valle selvaggia di Aster" fetchpriority="high"><div class="hero-meta"><span class="overline">PROGRAMMA AURORA / SETTORE 04</span><h2>Avamposto ${escape(p.name)}</h2><p>Stazione scientifica nelle terre selvagge</p></div><div class="hero-coordinates">ASTER<br><b>${p.baseTile.x} | ${p.baseTile.y}</b></div><div class="hero-actions"><button class="primary" data-page="base">Sviluppa strutture</button><button class="quiet" data-page="map">Apri territorio →</button></div></div><div class="overview-stats"><div><span>Specie documentate</span><strong>${registered(p).size}<small> / 151</small></strong></div><div><span>Capacità habitat</span><strong>${p.creatures.length}<small> / ${p.capacity}</small></strong></div><div><span>Prestigio scientifico</span><strong>${num(p.prestige)}</strong></div><div><span>Magazzino per risorsa</span><strong>${num(p.cap)}</strong></div></div><section class="operations"><div class="panel-heading"><h2>Attività dell’avamposto</h2><span>AGGIORNAMENTO IN DIRETTA</span></div><div class="operation-row"><span class="op-icon">⌂</span><div><strong>Costruzione</strong><p>${job?escape(catalog.buildings.find(b=>b.id===job.id).name)+' → Liv. '+(p.buildings[job.id]+1):'Nessuna costruzione in corso'}</p></div><span class="op-time">${job?time(job.end-state.time):'Libera'}</span><button class="quiet" data-page="base">Strutture</button></div><div class="operation-row"><span class="op-icon">⚗</span><div><strong>Ricerca</strong><p>${tech?escape(catalog.research.find(r=>r.id===tech.id).name):'Laboratorio disponibile'}</p></div><span class="op-time">${tech?time(tech.end-state.time):'Libera'}</span><button class="quiet" data-page="research">Laboratorio</button></div><div class="operation-row"><span class="op-icon">⌖</span><div><strong>Operazioni sul campo</strong><p>${escape(activity)}${p.betaMission?` · Beta: ${catalog.missions[p.betaMission.type].name}`:p.betaLock?.ok?' · Beta disponibile':''}</p></div><span class="op-time">${eta}</span><button class="quiet" data-page="map">Territorio</button></div>${craftQueue(p)}</section>`;
 }
 if(page==='missions'){
  pane.innerHTML=`<div class="help-card"><strong>Operazioni in tempo reale persistente.</strong> La squadra è impegnata dalla partenza fino al rientro. Non serve restare online: il server gestisce le scadenze e conserva l'esito. Velocità determinata dal Pokémon più lento.</div>${missionPanel(p)}<div class="cards mission-types">${Object.entries(catalog.missions).map(([id,m])=>`<article class="card"><h3>${m.name}</h3><p>${m.desc}</p>${p.locks.missions[id].ok?"":`<div class="requirement">🔒 ${p.locks.missions[id].missing.map(escape).join("<br>")}</div>`}<div class="cost">${m.food} cibo · Operazione ${time(m.work)}</div><button class="quiet" data-page="map">Scegli casella →</button></article>`).join('')}</div>`;
 }
 if(page==='reports'){
  pane.innerHTML=p.reports.length?`<div class="report-list">${p.reports.map(r=>`<article class="card report"><div class="card-top"><span class="tag">${squadName(r.squad)} · ${catalog.missions[r.type]?.name||'Missione'} (${r.coords.x}|${r.coords.y})</span><time>${new Date(r.time).toLocaleString('it-IT')}</time></div><h3>${escape(r.title)}</h3><p>${escape(r.text)}</p><div class="cost">${Object.keys(r.resources||{}).length?costText(r.resources):'Nessun carico'} · ${r.xp||0} XP · ${r.prestige||0} prestigio</div><span class="tag">${r.returned?'✓ SQUADRA RIENTRATA · CARICO CONSEGNATO':'RAPPORTO DAL CAMPO · RIENTRO IN CORSO'}</span></article>`).join('')}</div>`:'<div class="help-card"><strong>Nessun rapporto disponibile.</strong> Invia la prima ricognizione dal Territorio: il rapporto apparirà al termine dell’operazione sul campo.</div>';
 }

 if(page==='technology')renderTechnology();
 if(page==='staff')renderStaff();
 if(page==='collection')renderCollection();
 if(page==='base'){ensureProgression();
  pane.innerHTML=`<div class="help-card"><button class="quiet" data-page="technology">Albero tecnologico →</button> <strong>Strutture interconnesse.</strong> I requisiti indicano cosa manca per il prossimo livello. Una costruzione alla volta; energia e tecnologie sbloccano i rami avanzati. <button class="quiet" data-page="energy">Bilancio energetico →</button></div><div class="cards">${catalog.buildings.map(b=>{const cost=p.buildCosts[b.id],lock=p.locks.buildings[b.id],job=p.buildJob?.id===b.id;return `<article class="card ${lock.ok?'':'locked-card'}">${facilityArt(b.id)}<div class="card-top"><span class="facility-category">STRUTTURA</span><span class="tag">LIV. ${p.buildings[b.id]}</span></div><h3>${b.name}</h3><p>${b.desc}</p>${levelEffectsMarkup('building',b.id)}<button class="quiet tech-detail-link" data-tech-kind="building" data-tech-id="${b.id}">Requisiti e livelli →</button>${p.buildings[b.id]?`<div class="small muted">Personale ${p.workforce[b.id].workers.length}/${p.workforce[b.id].slots} · Operatività ${Math.round(p.workforce[b.id].coverage*100)}%</div><button class="quiet" data-page="staff">Gestisci personale →</button>`:''}${catalog.recipes.some(r=>r.structure===b.id)?`<div class="small muted">Strumenti: ${catalog.recipes.filter(r=>r.structure===b.id).map(r=>r.name).join(", ")}</div>`:""}<div class="requirement ${lock.ok?'fulfilled':''}">${lock.ok?'✓ Prerequisiti soddisfatti':'🔒 '+lock.missing.map(escape).join('<br>')}</div><div class="cost">${costText(cost)}<br>Durata ${time(p.buildDurations[b.id])}</div><button class="${job?'quiet':'primary'}" data-command="build" data-id="${b.id}" ${p.buildJob||!lock.ok||!afford(cost)?'disabled':''}>${job?'In corso · '+time(p.buildJob.end-state.time):p.buildings[b.id]?'Migliora →':'Costruisci →'}</button></article>`}).join('')}</div>`;
 }
 if(page==='research'){ensureProgression();
  pane.innerHTML=`<div class="help-card"><button class="quiet" data-page="technology">Albero tecnologico →</button> <strong>Laboratorio ${p.buildings.lab}</strong> · Limite ${Math.min(20,p.buildings.lab*2)} livelli per tecnologia. Il ricercatore dirige le ricerche. I Pokémon assegnati al Laboratorio possono ridurre tempi e costi. Alcune ricerche richiedono potenza installata. ${p.researchJob?'In corso: '+escape(catalog.research.find(r=>r.id===p.researchJob.id).name)+' · '+time(p.researchJob.end-state.time):''}</div><div class="cards">${catalog.research.map(r=>{const lock=p.locks.research[r.id],cost=p.researchCosts[r.id];return `<article class="card ${lock.ok?'':'locked-card'}">${facilityArt(researchArt[r.id])}<div class="card-top"><span class="facility-category">TECNOLOGIA</span><span class="tag">LIV. ${p.research[r.id]}</span></div><h3>${r.name}</h3><p>${r.desc}</p>${levelEffectsMarkup('research',r.id)}<button class="quiet tech-detail-link" data-tech-kind="research" data-tech-id="${r.id}">Requisiti e livelli →</button><div class="requirement ${lock.ok?'fulfilled':''}">${lock.ok?'✓ Prerequisiti soddisfatti':'🔒 '+lock.missing.map(escape).join('<br>')}</div><div class="cost">${costText(cost)}<br>Durata ${time(p.researchDurations[r.id])}</div><button class="primary" data-command="research" data-id="${r.id}" ${p.researchJob||!lock.ok||!afford(cost)?'disabled':''}>Ricerca →</button></article>`}).join('')}</div>`;
 }
 if(page==='energy'){
  const e=p.power;
  pane.innerHTML=`<div class="energy-summary"><div><span>Potenza prodotta</span><strong>${num(e.produced)}</strong></div><div><span>Richiesta impianti</span><strong>${num(e.consumed)}</strong></div><div class="${e.balance<0?'power-deficit':''}"><span>Bilancio disponibile</span><strong>${e.balance>0?'+':''}${num(e.balance)}</strong></div><div><span>Efficienza estrazione</span><strong>${Math.round(e.factor*100)}%</strong></div></div><div class="help-card">L’energia è <strong>capacità istantanea</strong>: non si accumula, non si trasporta, non si compra e non viene spesa come un materiale. Quando manca, gli impianti producono in proporzione. Riduci un impianto o sviluppa Centrale solare ed Energetica. I rifornimenti minimi restano attivi per evitare blocchi. ${Object.entries(p.rates).some(([r,v])=>v===0&&p.resources[r]>=p.cap)?'<p class="storage-notice">Magazzini pieni: la produzione di quelle risorse è sospesa, anche se la rete elettrica è efficiente.</p>':''}</div><div class="energy-table"><div class="energy-row energy-head"><span>Impianto</span><span>Regolazione</span><span>Potenza</span><span>Totale risorsa / h</span></div>${['generator','quarry','farm','refinery'].map(id=>{const b=catalog.buildings.find(b=>b.id===id),resource={quarry:'materials',farm:'food',refinery:'reagents'}[id];return `<div class="energy-row"><strong>${b.name}<small>Livello ${p.buildings[id]}</small></strong><select data-production="${id}" aria-label="Produzione ${b.name}" ${!p.buildings[id]?'disabled':''}>${Array.from({length:11},(_,i)=>i*10).map(n=>`<option ${p.productionSettings[id]===n?'selected':''} value="${n}">${n}%</option>`).join('')}</select><span>${id==='generator'?'+ '+num(e.produced):'− '+(e.byPlant[id]||0).toLocaleString('it-IT',{maximumFractionDigits:1})}</span><span>${resource?num(p.rates[resource]*3600)+' '+labels[resource].toLowerCase()+'/h':'Potenza continua'}</span></div>`}).join('')}</div>`;
 }
 if(page==='craft'){
  pane.innerHTML=`<div class="help-card"><strong>Produzione degli strumenti.</strong> Ogni ricetta dipende da una struttura e da tecnologie. Un lotto occupa la coda di fabbricazione fino alla consegna. Non ci sono acquisti istantanei di strumenti.</div><div class="help-card"><strong>Materiali di campo</strong>${fieldInventory(p)}<p class="small muted">I campioni arrivano dai siti specializzati. La ricetta indica quali servono.</p></div>${p.craftJob?`<div class="help-card"><strong>In lavorazione: ${p.craftJob.quantity} × ${catalog.recipes.find(r=>r.id===p.craftJob.id).name}</strong> · ${time(p.craftJob.end-state.time)}</div>`:''}<div class="cards">${catalog.recipes.map(r=>{const lock=p.locks.recipes[r.id],count=itemCount(p,r.id);return `<article class="card ${lock.ok?'':'locked-card'}">${facilityArt(r.structure)}<div class="card-top"><span class="tag">${catalog.buildings.find(b=>b.id===r.structure).name}</span><span class="small muted">${count} disponibili</span></div><h3>${r.name}</h3><p>${r.desc}</p><div class="requirement ${lock.ok?'fulfilled':''}">${lock.ok?'✓ Ricetta sbloccata':'🔒 '+lock.missing.map(escape).join('<br>')}</div><div class="cost">Per unità: ${costText(p.recipeCosts[r.id])}<br>Durata ${time(p.recipeDurations[r.id])}</div>${Object.keys(r.cost).filter(id=>catalog.fieldMaterials?.[id]).map(id=>`<button class="quiet" data-find-material="${id}">Cerca ${escape(labels[id].toLowerCase())} →</button>`).join('')}<div class="craft-controls"><label>Lotto <select id="qty-${r.id}" aria-label="Quantità ${r.name}"><option>1</option><option>5</option><option>10</option><option>20</option></select></label><button class="primary" data-craft="${r.id}" ${p.craftJob||!lock.ok||!afford(p.recipeCosts[r.id])?'disabled':''}>Fabbrica →</button></div></article>`}).join('')}</div>`;
 }
 if(page==='market'){
  const locked=!p.buildings.depot;
  pane.innerHTML=`${playerMarketMarkup(p)}<h2 class="market-heading">Mercato regionale</h2><div class="help-card">${locked?'<strong>🔒 Mercato non disponibile.</strong> Costruisci il Deposito logistico 1 per aprire gli scambi.':'Mercato regionale: scambia risorse immagazzinabili. L’energia non è una merce.'}</div><div class="cards">${['materials','food','reagents'].map(r=>{const buy=r==='reagents'?120:80,sell=r==='reagents'?60:40;return `<article class="card"><span class="tag">${num(p.resources[r])} IN DEPOSITO</span><h3>${labels[r]}</h3><p>Lotto da 100 · Capienza ${num(p.cap)}</p><button class="primary" data-market="buy" data-resource="${r}" ${locked||p.resources.credits<buy?'disabled':''}>Compra · ${buy} crediti</button><button class="quiet" data-market="sell" data-resource="${r}" ${locked||p.resources[r]<100?'disabled':''}>Vendi · +${sell} crediti</button></article>`}).join('')}</div>`;
 }

 if(page==='quests'){pane.innerHTML=`<div class="cards">${catalog.quests.map(q=>{const done=p.claimed.includes(q.id),ready=p.progress[q.id]>=q.goal;return `<article class="card"><span class="tag">${done?'COMPLETATO':ready?'PREMIO DISPONIBILE':'IN CORSO'}</span><h3>${q.name}</h3><p>${q.desc}</p><div class="cost">${Math.min(p.progress[q.id],q.goal)}/${q.goal} · ${costText(q.reward)}</div><button class="${done?'quiet':'primary'}" data-command="claim" data-id="${q.id}" ${done||!ready?'disabled':''}>${done?'✓ Riscattato':'Riscatta premio'}</button></article>`}).join('')}</div>`}
 if(page==='ranking'){pane.innerHTML=`<div class="help-card">Il tuo prestigio: <strong>${num(p.prestige)}</strong> · Ogni vittoria, cattura e boss contribuisce alla tua reputazione.</div><table class="ranking"><thead><tr><th>#</th><th>Allenatore</th><th class="hide-mobile">Alleanza</th><th>Pokémon</th><th>Prestigio</th></tr></thead><tbody>${state.ranking.map((r,i)=>`<tr class="${r.id===p.id?'you':''}"><td>${i+1}</td><td>${escape(r.name)}${r.id===p.id?' · Tu':''}</td><td class="hide-mobile">${escape(r.alliance)}</td><td>${r.collection}</td><td>${num(r.prestige)}</td></tr>`).join('')}</tbody></table>`}
 if(page==='alliance'){const own=state.alliances.find(a=>a.id===p.alliance);pane.innerHTML=(own?`<div class="help-card"><h3>⚑ ${escape(own.name)}</h3><p>${own.members}/20 membri · Usa il canale Alleanza nella Radio Aurora.</p><button class="quiet" data-leave-alliance>Lascia alleanza</button></div>${allianceDevelopmentMarkup(p)}`:`<div class="help-card"><strong>Fonda un gruppo di esploratori.</strong><form class="alliance-form" id="alliance-form"><input name="name" minlength="3" maxlength="24" placeholder="Nome alleanza" aria-label="Nome della nuova alleanza" required><button class="primary" type="submit">Crea alleanza</button></form></div>`)+`<div class="cards">${state.alliances.length?state.alliances.map(a=>`<article class="card"><span class="building-icon">⚑</span><h3>${escape(a.name)}</h3><p>${a.members}/20 ricercatori</p><button class="primary" data-join-alliance="${a.id}" ${p.alliance||a.members>=20?'disabled':''}>Unisciti →</button></article>`).join(''):'<div class="help-card">Non ci sono ancora alleanze. Crea la prima.</div>'}</div>`}
}
function renderCollection(){const p=state.me;const owned=registered(p);const list=dexMode==='all'?catalog.species:p.creatures;$('#page-content').innerHTML=`<div class="collection-toolbar"><span class="tag">${owned.size}/151 SPECIE</span><span class="muted small">Habitat ${p.creatures.length}/${p.capacity}</span><input id="dex-search" placeholder="Cerca un Pokémon…" aria-label="Cerca Pokémon" value="${escape(dexSearch)}"></div><div class="dex-tabs"><button class="quiet ${dexMode==='owned'?'active':''}" data-dex="owned">I tuoi Pokémon</button><button class="quiet ${dexMode==='all'?'active':''}" data-dex="all">Pokédex completo</button></div>${collectionFilters()}<div class="dex-grid">${list.filter(c=>(c.speciesData||c).name.toLowerCase().includes(dexSearch.toLowerCase())&&(!dexType||(c.speciesData||c).types.includes(dexType))&&(!dexRarity||c.talent?.rank===Number(dexRarity)-1)&&(!dexDuty||(dexDuty==='work'?!!c.assignment:dexDuty==='team'?p.team.includes(c.id):!c.assignment&&!p.team.includes(c.id)))).map(c=>{const s=c.speciesData||c,inTeam=p.team.includes(c.id),unknown=dexMode==='all'&&!owned.has(s.id);return `<article class="dex-card ${inTeam?'in-team':''} ${unknown?'unknown':''}"><span class="dex-num">#${String(s.dex).padStart(3,'0')}</span>${sprite(s)}<strong>${escape(s.name)}</strong><span class="type">${s.types.join(" / ")}</span>${dexMode==='owned'?`<div class="small muted">Liv. ${c.level} · ${num(c.hp)}/${c.maxHp} PS</div>${talentMarkup(c)}<div class="small muted">${travelling(p,c.id)?"In spedizione":c.assignment?buildingName(c.assignment):inTeam?"Squadra Alfa":"Riserva"}</div>${c.assignment?'<button class="quiet" data-page="staff">Gestisci mansione →</button>':''}<button class="${inTeam?'quiet':'primary'}" data-team-id="${c.id}" ${(inTeam&&p.team.length===1)||c.assignment||travelling(p,c.id)?'disabled':''}>${inTeam?'✓ In squadra · Rimuovi':p.team.length>=p.teamLimit?'Squadra piena':'Aggiungi alla squadra'}</button>`:`<div class="small muted">${unknown?'Da scoprire':'✓ Registrato'}</div>`}</article>`}).join('')}</div>`}

document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){navigate(b.dataset.page);return}if(b.dataset.select){selected=b.dataset.select;if(b.hasAttribute('data-gather-site')&&state.me.locks.missions.gather.ok)missionKind='gather';renderTarget();renderMap();return}if(b.dataset.command){b.disabled=true;await command({type:b.dataset.command,id:b.dataset.id,squad:b.dataset.squad});render(true);return}if(b.dataset.market){await command({type:'market',side:b.dataset.market,resource:b.dataset.resource});return}if(b.dataset.dex){dexMode=b.dataset.dex;renderCollection();return}if(b.dataset.teamId){const p=state.me,id=b.dataset.teamId,ids=p.team.includes(id)?p.team.filter(x=>x!==id):[...p.team,id];if(ids.length>state.me.teamLimit){toast('Rimuovi prima un membro dalla squadra.');return}await command({type:'team',ids});return}if(b.dataset.joinAlliance){await command({type:'alliance',action:'join',id:b.dataset.joinAlliance});return}if(b.hasAttribute('data-leave-alliance'))await command({type:'alliance',action:'leave'});if(b.id==='center-map'){camera.x=state.me.baseTile.x;camera.y=state.me.baseTile.y;renderMap(true)}});
document.addEventListener('input',e=>{if(e.target.id==='dex-search'){dexSearch=e.target.value;const pos=e.target.selectionStart;renderCollection();$('#dex-search').focus();$('#dex-search').setSelectionRange(pos,pos)}});
document.addEventListener('submit',async e=>{if(e.target.id==='alliance-form'){e.preventDefault();await command({type:'alliance',action:'create',name:new FormData(e.target).get('name')})}});
$('#chat-channel').onchange=renderChat;$('#chat-form').onsubmit=async e=>{e.preventDefault();if(await command({type:'chat',text:$('#chat-text').value,channel:$('#chat-channel').value}))$('#chat-text').value=''};
$('#join-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button[type=submit]');b.disabled=true;try{const snapshot=await api(loginMode?'/api/login':'/api/join',{name:$('#trainer').value,starter,password:$('#account-password').value||undefined});$('#account-password').value='';openGame(snapshot)}catch(err){$('#join-error').textContent=err.message}finally{b.disabled=false}};


// Mappa territoriale a coordinate intere: il client non simula movimenti o combattimenti.
let camera={x:-6,y:6,size:11},mapSignature='';
function renderMap(force=false){
 if(!state||page!=='map')return;const grid=$('#world');
 let side=innerWidth<600?7:camera.size;const half=Math.floor(side/2),rows=7;const {min,max}=state.world;camera.x=Math.max(min+half,Math.min(max-half,camera.x));camera.y=Math.max(min+3,Math.min(max-3,camera.y));
 const byCoordinate=new Map(state.world.tiles.map(t=>[t.x+":"+t.y,t]));
 const tiles=[];for(let row=0;row<rows;row++)for(let col=0;col<side;col++){const x=camera.x-half+col,y=camera.y+3-row;tiles.push(byCoordinate.get(x+":"+y))}
 const key=JSON.stringify([camera,side,selected,state.me.mission?.id,state.me.betaMission?.id,tiles.map(t=>[t.known,t.stock,t.owner?.id])]);if(key===mapSignature&&!force)return;mapSignature=key;grid.style.setProperty('--map-side',side);
 grid.innerHTML=tiles.map(t=>{const b=catalog.biomes[t.biome],k=t.x+':'+t.y,own=t.owner?.id===state.me.id,teams=[state.me.mission,state.me.betaMission].filter(m=>m?.destination.x===t.x&&m.destination.y===t.y),active=teams.length>0;return `<button type="button" class="terrain-tile biome-${t.biome} ${t.known?'known':'unknown'} ${t.owner?'settlement':''} ${own?'own':''} ${active?'destination':''}" data-tile="${k}" aria-pressed="${selected===k}" aria-label="${t.owner?'Avamposto '+escape(t.owner.name):b.name} (${t.x}|${t.y}), ${t.known?'esplorato':'da esplorare'}"><span class="tile-coord">${t.x}|${t.y}</span><span class="tile-art">${t.owner?'⌂':b.icon}</span>${t.site?.type==='deep'?'<span class="site-marker" aria-hidden="true">◆</span>':''}<span class="tile-caption">${t.owner?escape(t.owner.name):active?teams.map(m=>squadName(m.squad).toUpperCase()).join(' + '):!t.known?'?':b.name}</span></button>`}).join('');
 $('#map-position').textContent=`Settore (${camera.x}|${camera.y})`;
}
function missionPanel(p) {
 const alpha = missionCard(p.mission,'alpha');
 const beta = p.betaLock?.ok ? missionCard(p.betaMission,'beta') : p.betaLock ? `<div class="mission-idle"><strong>Squadra Beta</strong><br><small>Da sbloccare · ${p.betaLock.missing.map(escape).join(' · ')}</small></div>` : '';
 return `<div class="squad-missions">${alpha}${beta}</div>`;
}
function missionCard(m,squad){
 if(!m)return `<div class="mission-idle"><strong>Squadra ${squadName(squad)}</strong><br><small>Disponibile · scegli un habitat nel Territorio.</small></div>`;
 const phase={outbound:'In viaggio',onsite:'Operazione sul campo',returning:'Rientro'},due=m.phase==='outbound'?m.arriveAt:m.phase==='onsite'?m.completeAt:m.returnAt;
 return `<div class="mission-active"><span class="tag">${squadName(squad)} · ${phase[m.phase]}</span><h3>${catalog.missions[m.type].name}</h3><p>Destinazione (${m.destination.x}|${m.destination.y})</p><strong class="mission-countdown">${time(due-state.time)}</strong><div class="progress"><span style="width:${Math.min(100,Math.max(2,(state.time-m.departAt)/(m.returnAt-m.departAt)*100))}%"></span></div><small>Rientro previsto ${new Date(m.returnAt).toLocaleTimeString('it-IT')}</small><button class="quiet" data-page="missions">Dettagli spedizione</button>${m.phase!=='returning'?`<button class="quiet" data-command="recall" data-squad="${squad}">Richiama ${squadName(squad)}</button>`:''}</div>`;
}
document.addEventListener('change',e=>{if(e.target.id==='mission-kind'){missionKind=e.target.value;missionTool='';renderTarget()}if(e.target.id==='mission-species'){missionSpecies=e.target.value;missionTalentType='';renderTarget()}if(e.target.id==='mission-talent-type'){missionTalentType=e.target.value;renderTarget()}if(e.target.id==='mission-ball')missionBall=e.target.value;if(e.target.id==='mission-tool'){missionTool=e.target.value;renderTarget();renderGatherSites()}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tile){selected=b.dataset.tile;renderTarget();renderMap()}if(b.hasAttribute('data-dispatch')){const tile=selectedObject();if(!tile)return;missionSpecies=$('#mission-species')?.value||tile.encounters[0];b.disabled=true;if(await command({type:'dispatch',squad:selectedSquad,roster:selectedSquad==='beta'?betaRoster(state.me).map(c=>c.id):undefined,kind:missionKind,x:tile.x,y:tile.y,species:missionSpecies,ball:$('#mission-ball')?.value||'ball',tool:$('#mission-tool')?.value||'',talentType:$('#mission-talent-type')?.value||(sData(missionSpecies)?.types.length===1?sData(missionSpecies).types[0]:undefined)})){missionTalentType='';toast('Spedizione inviata. I tempi sono gestiti dal server.')}renderTarget()}if(b.dataset.pan){const [dx,dy]=b.dataset.pan.split(',').map(Number);camera.x+=dx;camera.y+=dy;renderMap(true)}if(b.id==='go-home'||b.id==='center-map'){camera.x=state.me.baseTile.x;camera.y=state.me.baseTile.y;renderMap(true)}});
$('#zoom-in').onclick=()=>{camera.size=Math.max(7,camera.size-2);renderMap(true)};$('#zoom-out').onclick=()=>{camera.size=Math.min(13,camera.size+2);renderMap(true)};
window.addEventListener('resize',()=>renderMap(true));

document.addEventListener('error',e=>{if(e.target instanceof HTMLImageElement){e.target.alt='◒ '+e.target.alt;e.target.style.fontSize='10px';e.target.style.objectFit='contain'}},true);

function syncAuthMode(){$('#starters').hidden=loginMode;$('#account-password').required=loginMode||config.authRequired;$('#account-password').autocomplete=loginMode?'current-password':'new-password';$('#auth-mode-toggle').textContent=loginMode?'Nuovo ricercatore? Crea un avamposto':'Hai già un account? Accedi';$('#password-label').textContent=loginMode||config.authRequired?'Password':'Password (consigliata)';$('#join-form button[type=submit]').textContent=loginMode?'Accedi →':'Inizia la missione →';$('#join-error').textContent=''}
$('#auth-mode-toggle').onclick=()=>{loginMode=!loginMode;syncAuthMode()};
document.addEventListener('submit',async e=>{if(e.target.id==='claim-account'){e.preventDefault();try{await api('/api/account/claim',{password:$('#claim-password').value});$('#claim-password').value='';toast('Account protetto. Ora puoi accedere da altri browser.')}catch(err){toast(err.message)}}});
document.addEventListener('click',async e=>{if(e.target.closest('[data-logout]')){try{await api('/api/logout',{});location.reload()}catch(err){toast(err.message)}}});
try{config=await api('/api/config');syncAuthMode();catalog=await api('/api/catalog');for(const [id,material] of Object.entries(catalog.fieldMaterials??{})){labels[id]=material.name;$('#site-resource').add(new Option(material.name,id));}$('#starters').innerHTML=['bulbasaur','charmander','squirtle'].map(id=>{const s=sData(id);return `<button type="button" class="starter" data-starter="${id}" aria-pressed="${id===starter}">${sprite(s)}<strong>${s.name}</strong><small>${s.types.join(" / ").toUpperCase()}</small></button>`}).join('');document.querySelectorAll('[data-starter]').forEach(b=>b.onclick=()=>{starter=b.dataset.starter;document.querySelectorAll('[data-starter]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.starter===starter)))});try{openGame(await api('/api/me'))}catch(err){if(err.message.includes('Scegli nome'))$('#welcome').hidden=false;else throw err}}catch(err){$('#fatal').hidden=false;$('#fatal').textContent='Impossibile avviare il gioco: '+err.message+'. Avvia il server con node server.mjs e ricarica questa pagina.'}





function buildingName(id){return catalog.buildings.find(b=>b.id===id)?.name||id}
function talentDetails(t){const effects=catalog.workforce.effects;return `${Math.round(t.value*100)}% ${effects[t.effect]} · ${t.facilities.map(buildingName).concat(t.missions.map(id=>catalog.missions[id].name)).join(', ')}`}
function talentMarkup(c){const t=c.talent;if(!t)return '<span class="talent pending">Abilità da assegnare · apri Personale</span>';return `<div class="talent rarity-${t.rank}"><strong>${escape(t.name)}</strong><span>${escape(t.type)} · ${t.rarity}</span><small>${escape(talentDetails(t))}</small></div>`}
function talentCaptureMarkup(id){const s=sData(id);if(!s)return '';const types=s.types,chosen=types.length===1?types[0]:types.includes(missionTalentType)?missionTalentType:'';return `<div class="capture-talent"><label>Tipo dell’abilità per questa cattura<select id="mission-talent-type" ${types.length===1?'disabled':''}><option value="" ${!chosen?'selected':''}>Scegli un tipo…</option>${types.map(t=>`<option value="${t}" ${chosen===t?'selected':''}>${t}</option>`).join('')}</select></label>${chosen?talentPoolMarkup(chosen):'<p class="small muted">Scegli a ogni cattura. Entrambi i tipi restano validi per lavoro e combattimento.</p>'}</div>`}
function talentPoolMarkup(type){return `<div class="talent-pool">${catalog.workforce.talents[type].map((t,i)=>`<div class="rarity-${i}"><strong>${escape(t.name)}</strong><span>${catalog.workforce.rarities[i].chance}% · ${catalog.workforce.rarities[i].name}</span><small>${escape(talentDetails(t))}</small></div>`).join('')}<p class="small muted">Garanzia rara alla 40ª cattura riuscita senza rara di tipo ${type}. Progressi: ${state.me.talentMisses[type]||0}/39.</p></div>`}
function collectionFilters(){return `<div class="collection-filters"><label>Tipo<select id="dex-type"><option value="">Tutti</option>${Object.keys(catalog.workforce.talents).map(t=>`<option ${dexType===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Abilità<select id="dex-rarity"><option value="">Tutte</option>${catalog.workforce.rarities.map((r,i)=>`<option value="${i+1}" ${dexRarity===String(i+1)?'selected':''}>${r.name}</option>`).join('')}</select></label><label>Incarico<select id="dex-duty"><option value="">Tutti</option><option value="work" ${dexDuty==='work'?'selected':''}>Al lavoro</option><option value="team" ${dexDuty==='team'?'selected':''}>In squadra</option><option value="reserve" ${dexDuty==='reserve'?'selected':''}>Riserva</option></select></label></div>`}
function renderStaff(){
 const p=state.me,roles=catalog.workforce.roles;
 $('#page-content').innerHTML=`<div class="help-card"><strong>Un Pokémon, un incarico.</strong> Assegnarlo a una struttura lo rimuove dalla squadra. Liberarlo lo lascia in riserva: puoi rimetterlo in squadra dal Pokédex. I due tipi consentono entrambe le famiglie di lavoro; l’abilità resta una sola. <p class="small muted">Servizio del ricercatore: 70% senza personale. Automazione: almeno 85%, modulo da installare una volta. Ogni posto coperto aumenta l’operatività fino al 100%; i talenti aggiungono bonus locali entro i limiti. I pannelli solari restano autonomi.</p></div><div id="work-preview" class="work-preview" ${workPreview?'':'hidden'}>${workPreview?workPreviewMarkup():''}</div><h2 class="staff-heading">Operatività delle strutture</h2><div class="staff-facilities">${catalog.buildings.filter(b=>p.buildings[b.id]>0).map(b=>{const w=p.workforce[b.id],names=w.workers.map(id=>p.creatures.find(c=>c.id===id).speciesData.name);return `<article class="staff-facility"><img src="/assets/${b.id}.jpg" alt="" width="120" height="80" loading="lazy"><div><h3>${b.name} <span class="tag">${Math.round(w.coverage*100)}%</span></h3><p>${names.join(', ')||'Nessun lavoratore'} · ${w.workers.length}/${w.slots} posti</p><small>Tipi: ${roles[b.id].join(' / ')}</small><div class="staff-bonuses">${Object.entries(w.bonus).filter(([,n])=>n>0).map(([effect,n])=>`${Math.round(n*100)}% ${catalog.workforce.effects[effect]}`).join(' · ')||'Nessun bonus di abilità'}</div></div>${b.id!=='generator'?`<div class="staff-mode"><span class="tag">${w.mode==='auto'?'AUTOMAZIONE':'SERVIZIO'}</span><button class="quiet" data-work-mode="${b.id}" data-mode="${w.mode==='auto'?'service':'auto'}" ${w.mode!=='auto'&&p.buildings.hq<2?'disabled':''}>${w.mode==='auto'?'Passa a servizio':w.moduleInstalled?'Attiva automazione':'Installa automazione'}</button><small>${w.mode==='auto'?'Copertura minima 85%':w.moduleInstalled?'Modulo già installato':costText(w.automationCost)}</small>${['quarry','farm','refinery'].includes(b.id)?'<small>Automazione incompleta: +20% domanda elettrica</small>':''}</div>`:'<span class="tag">SOLARE AUTONOMO</span>'}</article>`}).join('')}</div><h2 class="staff-heading">I tuoi Pokémon</h2><div class="staff-roster">${p.creatures.map(c=>{const busy=travelling(p,c.id),inTeam=p.team.includes(c.id);return `<article class="card staff-creature"><div class="staff-creature-heading">${sprite(c.speciesData)}<div><h3>${escape(c.speciesData.name)}</h3><span class="type">${c.speciesData.types.join(' / ')}</span><p>Liv. ${c.level} · ${busy?'In spedizione':c.assignment?buildingName(c.assignment):inTeam?'Squadra Alfa':'Riserva'}</p></div></div>${talentMarkup(c)}${!c.talent?`<div class="initial-talent"><label>Tipo dell’abilità iniziale<select id="initial-type-${c.id}">${c.speciesData.types.map(t=>`<option ${(initialTalentDrafts[c.id]||c.speciesData.types[0])===t?'selected':''}>${t}</option>`).join('')}</select></label><button class="quiet" data-initial-talent="${c.id}" ${busy?'disabled':''}>Assegna abilità una volta</button><small>70% comune · 25% non comune · 5% rara. Nessuna nuova estrazione su questo esemplare.</small></div>`:''}<label>Mansione<select id="assignment-${c.id}" ${busy?'disabled':''}><option value="" ${!(assignmentDrafts[c.id]??c.assignment)?'selected':''}>Riserva</option>${catalog.buildings.filter(b=>p.buildings[b.id]&&c.speciesData.types.some(t=>roles[b.id].includes(t))).map(b=>`<option value="${b.id}" ${(assignmentDrafts[c.id]??c.assignment)===b.id?'selected':''}>${b.name} (${p.workforce[b.id].workers.length}/${p.workforce[b.id].slots})</option>`).join('')}</select></label><button class="primary" data-preview-assign="${c.id}" ${busy?'disabled':''}>Anteprima incarico →</button>${inTeam?'<small>Assegnandolo, la squadra avrà un membro in meno.</small>':''}</article>`}).join('')}</div>`;
}
function workPreviewMarkup(){const {before:a,after:b,cost}=workPreview.data;const cmd=workPreview.cmd,c=state.me.creatures.find(c=>c.id===cmd.creatureId),title=cmd.type==='assign'?c.speciesData.name+' → '+(cmd.structure?buildingName(cmd.structure):'Riserva'):buildingName(cmd.structure)+' → '+(cmd.mode==='auto'?'Automazione':'Servizio');return `<h3>${escape(title)}</h3><div class="work-preview-values">${['materials','food','reagents'].map(r=>`<div><span>${labels[r]}/h</span><strong>${num(a.hourly[r])} → ${num(b.hourly[r])}</strong></div>`).join('')}<div><span>Bilancio energia</span><strong>${a.power.balance} → ${b.power.balance}</strong></div><div><span>Membri squadra</span><strong>${a.team} → ${b.team}</strong></div></div>${Object.entries(b.jobs).map(([id,n])=>`<p>${{buildJob:'Costruzione',researchJob:'Ricerca',craftJob:'Fabbricazione'}[id]} residua: ${time(a.jobs[id])} → ${time(n)}</p>`).join('')}${!b.team?'<p class="requirement">La squadra sarà vuota. Prima di una spedizione, libera un Pokémon e aggiungilo alla squadra dal Pokédex.</p>':''}${Object.keys(cost).length?`<p>Installazione: ${costText(cost)}</p>`:''}<button class="primary" data-apply-work>Applica cambiamento</button> <button class="quiet" data-cancel-work>Annulla</button>`}
async function previewWork(cmd){try{const data=await api('/api/work-preview',cmd);workPreview={cmd,data};const panel=$('#work-preview');panel.hidden=false;panel.innerHTML=workPreviewMarkup();panel.scrollIntoView({block:'center',behavior:'smooth'})}catch(err){toast(err.message)}}
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.previewAssign){const id=b.dataset.previewAssign;await previewWork({type:'assign',creatureId:id,structure:$('#assignment-'+id).value||null})}
 if(b.dataset.workMode)await previewWork({type:'workMode',structure:b.dataset.workMode,mode:b.dataset.mode});
 if(b.hasAttribute('data-cancel-work')){workPreview=null;renderStaff()}
 if(b.hasAttribute('data-apply-work')&&workPreview){b.disabled=true;if(await command(workPreview.cmd)){workPreview=null;assignmentDrafts={};renderStaff();toast('Incarico aggiornato.');}}
 if(b.dataset.initialTalent){b.disabled=true;await command({type:'chooseTalent',creatureId:b.dataset.initialTalent,talentType:$('#initial-type-'+b.dataset.initialTalent).value})}
});
document.addEventListener('change',e=>{if(['dex-type','dex-rarity','dex-duty'].includes(e.target.id)){if(e.target.id==='dex-type')dexType=e.target.value;if(e.target.id==='dex-rarity')dexRarity=e.target.value;if(e.target.id==='dex-duty')dexDuty=e.target.value;renderCollection()}});


document.addEventListener('change',e=>{if(e.target.id.startsWith('assignment-'))assignmentDrafts[e.target.id.slice(11)]=e.target.value;if(e.target.id.startsWith('initial-type-'))initialTalentDrafts[e.target.id.slice(13)]=e.target.value;});

let progressionData=null,progressionKey='',progressionPending=false,techSelection={kind:'building',id:'hq'},techDetail=null,techTarget=null,techRequest=0,techSignature='';
function progressionSignature(){const p=state.me;return JSON.stringify([p.buildings,p.research,p.productionSettings,p.creatures.map(c=>[c.id,c.assignment,c.level,c.workTalent,c.hp>0]),p.team,p.workModes,p.mission?.id]);}
function metricNumber(value){return value===null?'—':value.toLocaleString('it-IT',{maximumFractionDigits:2});}
function comparisonMarkup(entry){if(!entry)return '<p class="small muted">Calcolo degli effetti…</p>';return `<div class="level-effects-title">${entry.next?`Livello ${entry.level} → ${entry.level+1}`:'Livello massimo 20'}</div><div class="level-effects-rows">${entry.current.map((m,i)=>{const next=entry.next?.[i],delta=next&&m.value!==null&&next.value!==null?next.value-m.value:0,good=delta&&(m.direction==='down'?delta<0:delta>0);return `<div><span>${escape(m.label)}</span><strong>${metricNumber(m.value)}${next?` <b class="${delta?(good?'metric-up':'metric-down'):''}">→ ${metricNumber(next.value)}</b>`:''} <small>${m.unit}</small></strong></div>`}).join('')}</div>`;}
function levelEffectsMarkup(kind,id){return `<div class="level-effects" data-level-effects="${kind}:${id}">${comparisonMarkup(progressionData?.[`${kind}:${id}`])}</div>`;}
async function ensureProgression(){const key=progressionSignature();if(progressionPending||key===progressionKey)return;progressionPending=true;try{const data=await api('/api/progression');progressionData=data;progressionKey=key;document.querySelectorAll('[data-level-effects]').forEach(el=>el.innerHTML=comparisonMarkup(data[el.dataset.levelEffects]));}catch(err){toast(err.message)}finally{progressionPending=false}}
function techDefinition(kind,id){return (kind==='building'?catalog.buildings:catalog.research).find(d=>d.id===id);}
function techOwned(kind,id){return state.me[kind==='building'?'buildings':'research'][id]||0;}
function techButton(kind,id,level,label){return `<button class="tech-node-link" data-tech-kind="${kind}" data-tech-id="${id}" ${level?`data-tech-level="${level}"`:''}>${escape(label||techDefinition(kind,id).name)}${level?' '+level:''}</button>`;}
function treeMarkup(kind,id,level,seen=new Set(),budget={n:0}){
 const node=catalog.technology[`${kind}:${id}:${level}`];if(!node)return '';const key=`${kind}:${id}:${level}`,met=techOwned(kind,id)>=level,duplicate=seen.has(key);budget.n++;if(budget.n>100)return `<li class="tech-tree-leaf">${techButton(kind,id,level)} · apri per i dettagli</li>`;
 const path=seen;path.add(key);return `<li class="${met?'tech-met':'tech-missing'}"><details ${!met&&!duplicate?'open':''}><summary><span class="tech-status-dot">${met?'✓':'○'}</span>${techButton(kind,id,level)}<small>Attuale ${techOwned(kind,id)}</small></summary>${!duplicate&&!met&&(node.edges.length||node.power)?`<ul>${node.edges.map(e=>treeMarkup(e.kind,e.id,e.level,path,budget)).join('')}${node.power?`<li class="${state.me.power.produced>=node.power?'tech-met':'tech-missing'}"><span class="tech-power">ϟ Potenza installata ${node.power} <small>Attuale ${state.me.power.produced}</small></span></li>`:''}</ul>`:'<p class="tech-tree-leaf">'+(met?'Requisito già raggiunto.':duplicate?'Requisito già mostrato in questo percorso.':'Nessun requisito precedente.')+'</p>'}</details></li>`;
}
async function loadTechnology(){const request=++techRequest,selection={...techSelection},signature=progressionSignature();try{const detail=await api(`/api/technology?kind=${selection.kind}&id=${selection.id}`);if(request!==techRequest)return;techDetail=detail;techSignature=signature;if(page==='technology')renderTechnology();}catch(err){if(request===techRequest)toast(err.message)}}
function renderTechnology(){
 const {kind,id}=techSelection,definition=techDefinition(kind,id),owned=techOwned(kind,id),level=techTarget??Math.min(20,owned+1);
 if(techDetail?.kind!==kind||techDetail?.id!==id){techDetail=null;loadTechnology();}else if(techSignature!==progressionSignature())loadTechnology();
 const detail=techDetail,art=kind==='building'?id:researchArt[id];
 $('#page-content').innerHTML=`<div class="help-card"><strong>Una mappa per pianificare.</strong> Scegli un elemento e il livello desiderato: l’albero mostra i prerequisiti, anche quelli indiretti. Verde = già raggiunto; ambra = da sviluppare. Ogni nodo è cliccabile. <p class="small muted">Gli effetti tengono fissi gli altri livelli, le impostazioni produttive e il personale attuale. Salendo di livello possono aumentare domanda elettrica e posti da coprire: una resa maggiore non è sempre immediata.</p></div><div class="tech-catalog">${['building','research'].map(k=>`<section><h2>${k==='building'?'Strutture':'Ricerche'}</h2><div>${(k==='building'?catalog.buildings:catalog.research).map(d=>{const n=techOwned(k,d.id),lock=state.me.locks[k==='building'?'buildings':'research'][d.id];return `<button class="tech-catalog-item ${k===kind&&d.id===id?'selected':''} ${n?'owned':lock.ok?'available':'unavailable'}" data-tech-kind="${k}" data-tech-id="${d.id}"><span>${k==='building'?d.icon:'⚗'}</span><strong>${escape(d.name)}</strong><small>${n?'Liv. '+n:lock.ok?'Requisiti soddisfatti':'Da sbloccare'}</small></button>`}).join('')}</div></section>`).join('')}</div><section class="tech-detail"><div class="tech-detail-hero"><img src="/assets/${art}.jpg" alt=""><div><span class="overline">${kind==='building'?'STRUTTURA':'RICERCA'} · LIVELLO ATTUALE ${owned}</span><h2>${escape(definition.name)}</h2><p>${escape(definition.desc)}</p><button class="quiet" data-page="${kind==='building'?'base':'research'}">${kind==='building'?'Vai alle costruzioni':'Vai alle ricerche'} →</button></div></div><div class="tech-detail-columns"><div><div class="tech-section-heading"><h3>Come raggiungere il livello</h3><label>Obiettivo<select id="tech-target" aria-label="Livello obiettivo">${Array.from({length:20},(_,i)=>i+1).map(n=>`<option value="${n}" ${n===level?'selected':''}>Livello ${n}${n<=owned?' · raggiunto':''}</option>`).join('')}</select></label></div><ul class="tech-tree">${treeMarkup(kind,id,level)}</ul><p class="small muted">Il livello precedente dello stesso elemento è incluso. Risorse, code occupate e tempi si verificano nella schermata di costruzione o ricerca.</p></div><div><h3>Costo per raggiungere il livello ${level}</h3>${detail?`<div class="cost">${costText(detail.levels[level].cost)}<br>Durata ${time(detail.levels[level].duration)}<br><small>Solo questo passaggio; prerequisiti esclusi.</small></div>`:'<p class="small muted">Calcolo…</p>'}<h3>Cosa cambia al prossimo livello</h3><div class="level-effects">${comparisonMarkup(detail)}</div>${detail&&level!==owned+1?`<h3>Livello ${Math.max(0,level-1)} → ${level}</h3><div class="level-effects">${comparisonMarkup({level:level-1,current:detail.levels[level-1].metrics,next:detail.levels[level].metrics})}</div>`:''}<p class="small muted">Produzioni prima della saturazione dei magazzini, al profilo ×${state.profile.speed}. I tempi base escludono bonus del personale; i tempi delle ricette li includono. La cattura finale resta limitata all’8–92% e dipende anche da squadra, bersaglio e strumenti.</p><h3>Contribuisce a sbloccare</h3><p class="small muted">Queste soglie sono un requisito: possono servire anche altri edifici o ricerche. Premi su una voce per vederli.</p>${detail?unlockMarkup(detail.unlocked||detail.unlocks):'<p class="small muted">Caricamento…</p>'}</div></div>${detail?levelTableMarkup(detail):''}</section>`;
}
function unlockMarkup(entries){const unique=new Map();for(const e of entries){const key=[e.kind,e.id||e.name,e.atLevel].join(':');if(!unique.has(key))unique.set(key,e);}const all=[...unique.values()],primary=all.filter(e=>!e.targetLevel||e.targetLevel===1),advanced=all.filter(e=>e.targetLevel>1);const list=items=>`<div class="tech-unlocks">${items.map(e=>`<div><span class="tag ${techOwned(techSelection.kind,techSelection.id)>=e.atLevel?'fulfilled':''}">LIV. ${e.atLevel}</span>${['building','research'].includes(e.kind)?techButton(e.kind,e.id,e.targetLevel,e.name):`<span>${escape(e.name)}</span>`}${e.kind==='recipe'?'<button class="quiet" data-page="craft">Ricetta →</button>':e.kind==='mission'?'<button class="quiet" data-page="missions">Missione →</button>':''}</div>`).join('')}</div>`;return (primary.length?list(primary):'<p class="small muted">Nessun nuovo elemento: migliora gli effetti o consente livelli superiori.</p>')+(advanced.length?`<details class="tech-advanced"><summary>Requisiti per livelli superiori (${advanced.length})</summary>${list(advanced)}</details>`:'');}

function levelTableMarkup(detail){const rows=detail.levels;return `<details class="tech-level-table"><summary>Tabella degli effetti · livelli 0–20</summary><p class="small muted">Simulazione di un solo livello alla volta, con il resto dell’avamposto invariato. Non include il costo cumulativo dei prerequisiti.</p><div class="tech-table-scroll"><table><thead><tr><th>Livello</th>${rows[0].metrics.map(m=>`<th>${escape(m.label)} ${m.unit?'('+m.unit+')':''}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr class="${r.level===detail.level?'current-level':''}"><th>${r.level}${r.level===detail.level?' · attuale':''}</th>${r.metrics.map(m=>`<td>${metricNumber(m.value)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-tech-id]');if(!b)return;e.preventDefault();techSelection={kind:b.dataset.techKind,id:b.dataset.techId};techTarget=b.dataset.techLevel?Number(b.dataset.techLevel):null;techDetail=null;navigate('technology');});
document.addEventListener('change',e=>{if(e.target.id==='tech-target'){techTarget=Number(e.target.value);renderTechnology();}});


document.addEventListener('change', e => {
 if (e.target.id==='mission-squad') {
  selectedSquad=e.target.value;
  renderTarget();
 }
 const id=e.target.dataset.betaMember;
 if (!id) return;
 if (!e.target.checked) betaRosterDraft.delete(id);
 else if (betaRoster(state.me).length<2) betaRosterDraft.add(id);
 else toast('La Squadra Beta ha al massimo due membri.');
 renderTarget();
});

$('#site-comparison').addEventListener('toggle',renderGatherSites);
$('#site-resource').addEventListener('change',renderGatherSites);

document.addEventListener('click',e=>{
 const button=e.target.closest('[data-find-material]');
 if (!button) return;
 navigate('map');
 $('#site-resource').value=button.dataset.findMaterial;
 $('#site-comparison').open=true;
 renderGatherSites();
 $('#site-comparison').scrollIntoView({block:'nearest'});
});

function playerMarketMarkup(p) {
 const market=state.market;
 if (!market) return '';
 const recipeName=id=>catalog.recipes.find(r=>r.id===id)?.name||id;
 const owned=catalog.recipes.filter(r=>r.id!=='rover'&&itemCount(p,r.id)>0);
 const canList=p.buildings.depot>0&&market.totalRovers>0&&owned.length>0;
 const offerRows=market.offers.map(offer=>{
  const mine=offer.sellerId===p.id;
  const unavailable=offer.available ? 'Crediti insufficienti' : 'Rover del venditore impegnati';
  return `<article class="market-offer"><div><strong>${offer.quantity} × ${escape(recipeName(offer.item))}</strong><small>${mine?'Tua offerta':escape(offer.sellerName)} · scade fra ${time(offer.expiresAt-state.time)}</small></div><div><strong>${num(offer.price)} crediti</strong><small>${mine?'Lotto in deposito':'Consegna in '+time(offer.travel)}</small></div><div>${mine?`<button class="quiet" data-trade="cancel" data-offer="${escape(offer.id)}">Ritira offerta</button>`:`<button class="primary" data-trade="buy" data-offer="${escape(offer.id)}" ${offer.available&&p.resources.credits>=offer.price?'':'disabled'}>Compra lotto</button>${!offer.available||p.resources.credits<offer.price?`<small>${unavailable}</small>`:''}`}</div></article>`;
 }).join('');
 const convoyRows=market.convoys.map(convoy=>{
  const outgoing=convoy.sellerId===p.id;
  const status=convoy.delivered?(outgoing?'Rover in rientro':'Ricevuto'):(outgoing?'Consegna in uscita':'Consegna in arrivo');
  const deadline=convoy.delivered?convoy.returnAt:convoy.arriveAt;
  return `<article class="market-offer"><div><strong>${escape(status)}</strong><small>${escape(outgoing?convoy.buyerName:convoy.sellerName)} · ${convoy.quantity} × ${escape(recipeName(convoy.item))}</small></div><span>${num(convoy.price)} crediti</span><span>${convoy.delivered&&!outgoing?'Consegnato':time(deadline-state.time)}</span></article>`;
 }).join('');
 return `<section class="player-market"><div class="help-card"><strong>Scambi tra giocatori</strong><p>Il venditore usa un rover del Deposito per consegnare il lotto. Gli strumenti e i crediti passano di mano all’arrivo.</p><p class="small muted">Flotta disponibile ${market.freeRovers}/${market.totalRovers}. I rover viaggiano separatamente dalle squadre Pokémon.</p></div>${canList?`<form id="market-offer-form" class="market-form"><label>Strumento<select name="item">${owned.map(r=>`<option value="${r.id}">${escape(r.name)} (${itemCount(p,r.id)})</option>`).join('')}</select></label><label>Quantità<input name="quantity" type="number" min="1" max="20" value="1" required></label><label>Prezzo totale in crediti<input name="price" type="number" min="1" max="100000" required></label><button class="primary" type="submit">Pubblica offerta</button></form><p class="small muted">Il lotto resta in deposito per 24 ore di gioco o fino all’acquisto. Puoi ritirarlo finché è disponibile.</p>`:`<div class="help-card"><p>${!p.buildings.depot?'Per vendere costruisci il Deposito logistico 1 e fabbrica un rover.':market.totalRovers===0?'Fabbrica un rover da carico nel Deposito per pubblicare offerte.':'Fabbrica uno strumento da mettere in vendita.'}</p><button class="quiet" data-page="craft">Vai a Strumenti →</button></div>`}<h2 class="market-heading">Offerte aperte</h2><div class="market-offers">${offerRows||'<p class="muted small">Nessuna offerta pubblicata.</p>'}</div><h2 class="market-heading">I tuoi convogli</h2><div class="market-offers">${convoyRows||'<p class="muted small">Nessun convoglio attivo.</p>'}</div></section>`;
}
document.addEventListener('submit',async e=>{
 if (e.target.id!=='market-offer-form') return;
 e.preventDefault();
 const values=new FormData(e.target);
 const button=e.target.querySelector('button[type=submit]');
 button.disabled=true;
 try {
  if (await command({type:'trade',action:'list',item:values.get('item'),quantity:Number(values.get('quantity')),price:Number(values.get('price'))})) toast('Offerta pubblicata. Lotto in deposito.');
 } finally {button.disabled=false;}
});
document.addEventListener('click',async e=>{
 const button=e.target.closest('[data-trade]');
 if (!button) return;
 button.disabled=true;
 try {
  if (await command({type:'trade',action:button.dataset.trade,id:button.dataset.offer})) toast(button.dataset.trade==='buy'?'Acquisto confermato. Rover in viaggio.':'Offerta ritirata. Lotto restituito.');
 } finally {button.disabled=false;}
});

function allianceDevelopmentMarkup(p) {
 const development=state.allianceDevelopment;
 if (!development) return '';
 const {points,level,levels,rates,personal}=development;
 const next=levels[level];
 const remaining=levels.at(-1).points-points;
 const progress=next?`${num(points)} / ${num(next.points)} punti · ${num(next.points-points)} al prossimo livello`:'Tutti i vantaggi sbloccati';
 const perks=levels.map((perk,index)=>`<div class="alliance-perk"><span class="tag">Livello ${index+1} · ${index<level?'Sbloccato':num(perk.points)+' punti'}</span><strong>${escape(perk.name)}</strong><small>${escape(perk.description)}</small></div>`).join('');
 const forms=Object.entries(rates).map(([resource,rate])=>{
  const max=Math.min(remaining,Math.floor(p.resources[resource]/rate))*rate;
  return `<form class="alliance-donation" data-donate-resource="${resource}"><label>${labels[resource]}<input aria-label="Quantità di ${labels[resource].toLowerCase()} da donare" name="quantity" type="number" min="${rate}" max="${max}" step="${rate}" value="${max>=rate?rate:0}" required ${max<rate?'disabled':''}></label><small>${rate} unità = 1 punto · disponibili ${num(p.resources[resource])}</small><button class="quiet" type="submit" ${max<rate?'disabled':''}>Dona ${labels[resource].toLowerCase()}</button></form>`;
 }).join('');
 return `<section class="help-card alliance-development"><h3>Sviluppo dell’alleanza · Livello ${level}</h3><p>${progress}</p><p class="small muted">Il tuo contributo · ${num(personal)} punti</p><div class="alliance-perks">${perks}</div>${next?`<p>Le risorse donate diventano punti permanenti dell’alleanza.</p><div class="alliance-donations">${forms}</div>`:''}</section>`;
}
document.addEventListener('submit',async e=>{
 const resource=e.target.dataset.donateResource;
 if (!resource) return;
 e.preventDefault();
 const button=e.target.querySelector('button[type=submit]');
 button.disabled=true;
 try {
  const quantity=Number(new FormData(e.target).get('quantity'));
  if (await command({type:'allianceDonate',resource,quantity})) toast('Donazione registrata.');
 } finally {button.disabled=false;}
});
